from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

def _ledger(data, priority, tax_base, refund):
    def rounded(n, mode):
        if mode == "half_up":
            return (n + 5000) // 10000
        return n // 10000

    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = ((event.get("sequence", 0), event.get("revision", 0), pos)
               if priority == "sequence_first" else
               (event.get("revision", 0), pos))
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), mode)
        base = raw if tax_base == "original" else net
        tax = rounded(base * event.get("tax_bp", 0), mode)
        total = net + tax
        if refund and event.get("kind") == "refund":
            total = -total
        key = str(event.get("account", "default")) + "|" + str(event.get("currency", "USD"))
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependency_resolver(data):
    from itertools import product

    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    states = [[None] + [row for row in packages[name]] for name in names]
    best = None
    best_versions = None

    for selection in product(*states):
        versions = {name: row["version"] for name, row in zip(names, selection) if row is not None}
        graph = {name: [] for name in versions}
        valid = True
        for name, bounds in data["roots"].items():
            if name not in versions or not bounds[0] <= versions[name] <= bounds[1]:
                valid = False
                break
        if not valid:
            continue
        for name, row in zip(names, selection):
            if row is None:
                continue
            if name in data.get("pins", {}) and versions[name] != data["pins"][name]:
                valid = False
                break
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if target not in versions or not dep["min"] <= versions[target] <= dep["max"]:
                    valid = False
                    break
                graph[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        # Installed packages must be precisely those reachable from roots.
        reachable = set()
        stack = list(data["roots"])
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(graph[name])
        if reachable != set(versions):
            continue

        done, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            if any(not visit(child) for child in graph[name]):
                return False
            active.remove(name)
            done.add(name)
            return True
        if not all(visit(name) for name in graph):
            continue

        vector = tuple(versions.get(name, -1) for name in names)
        if best is None or vector < best:
            best = vector
            best_versions = versions
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _quota_intervals(data):
    from itertools import combinations

    blocked = set(data.get("blocked", []))
    jobs = [job for job in data["jobs"] if job["id"] not in blocked]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value, best_ids = None, None
    for chosen in combinations(jobs, k):
        ids = tuple(sorted(job["id"] for job in chosen))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(chosen, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in chosen)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _temporal_routes(data):
    import heapq

    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bits.get(data["source"], 0)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start_state = (data["source"], initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"], *start_state)]
    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full and remaining == 0:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, next_remaining in options:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bits.get(next_node, 0)
                next_state = (next_node, next_mask, next_remaining)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, *next_state))
    return {"arrival": None}


